198: /* sends the image to the conversion function based on input format and
199:    desired output format.  Note that some of the less common conversions are
200:    currently two step processes. */
201: /* TODO: Write single step conversions where they may actually be useful */
202: int
203: v4l2_process_image(pgCameraObject *self, const void *image, int buffer_size,
204:                    SDL_Surface *surf)
205: {
206:     if (!surf)
207:         return 0;
208: 
209:     SDL_LockSurface(surf);
210: 
211:     switch (self->pixelformat) {
212:         case V4L2_PIX_FMT_RGB24:
213:             if (buffer_size >= self->size * 3) {
214:                 switch (self->color_out) {
215:                     case RGB_OUT:
216:                         rgb24_to_rgb(image, surf->pixels, self->size,
217:                                      surf->format);
218:                         break;
219:                     case HSV_OUT:
220:                         rgb_to_hsv(image, surf->pixels, self->size,
221:                                    V4L2_PIX_FMT_RGB24, surf->format);
222:                         break;
223:                     case YUV_OUT:
224:                         rgb_to_yuv(image, surf->pixels, self->size,
225:                                    V4L2_PIX_FMT_RGB24, surf->format);
226:                         break;
227:                 }
228:             }
229:             else {
230:                 SDL_UnlockSurface(surf);
231:                 return 0;
232:             }
233:             break;
234:         case V4L2_PIX_FMT_RGB444:
235:             if (buffer_size >= self->size * 2) {
236:                 switch (self->color_out) {
237:                     case RGB_OUT:
238:                         rgb444_to_rgb(image, surf->pixels, self->size,
239:                                       surf->format);
240:                         break;
241:                     case HSV_OUT:
242:                         rgb_to_hsv(image, surf->pixels, self->size,
243:                                    V4L2_PIX_FMT_RGB444, surf->format);
244:                         break;
245:                     case YUV_OUT:
246:                         rgb_to_yuv(image, surf->pixels, self->size,
247:                                    V4L2_PIX_FMT_RGB444, surf->format);
248:                         break;
249:                 }
250:             }
251:             else {
252:                 SDL_UnlockSurface(surf);
253:                 return 0;
254:             }
255:             break;
256:         case V4L2_PIX_FMT_YUYV:
257:             if (buffer_size >= self->size * 2) {
258:                 switch (self->color_out) {
259:                     case YUV_OUT:
260:                         yuyv_to_yuv(image, surf->pixels, self->size,
261:                                     surf->format);
262:                         break;
263:                     case RGB_OUT:
264:                         yuyv_to_rgb(image, surf->pixels, self->size,
265:                                     surf->format);
266:                         break;
267:                     case HSV_OUT:
268:                         yuyv_to_rgb(image, surf->pixels, self->size,
269:                                     surf->format);
270:                         rgb_to_hsv(surf->pixels, surf->pixels, self->size,
271:                                    V4L2_PIX_FMT_YUYV, surf->format);
272:                         break;
273:                 }
274:             }
275:             else {
276:                 SDL_UnlockSurface(surf);
277:                 return 0;
278:             }
279:             break;
280:         case V4L2_PIX_FMT_UYVY:
281:             if (buffer_size >= self->size * 2) {
282:                 switch (self->color_out) {
283:                     case YUV_OUT:
284:                         uyvy_to_yuv(image, surf->pixels, self->size,
285:                                     surf->format);
286:                         break;
287:                     case RGB_OUT:
288:                         uyvy_to_rgb(image, surf->pixels, self->size,
289:                                     surf->format);
290:                         break;
291:                     case HSV_OUT:
292:                         uyvy_to_rgb(image, surf->pixels, self->size,
293:                                     surf->format);
294:                         rgb_to_hsv(surf->pixels, surf->pixels, self->size,
295:                                    V4L2_PIX_FMT_YUYV, surf->format);
296:                         break;
297:                 }
298:             }
299:             else {
300:                 SDL_UnlockSurface(surf);
301:                 return 0;
302:             }
303:             break;
304:         case V4L2_PIX_FMT_SBGGR8:
305:             if (buffer_size >= self->size) {
306:                 switch (self->color_out) {
307:                     case RGB_OUT:
308:                         sbggr8_to_rgb(image, surf->pixels, self->width,
309:                                       self->height, surf->format);
310:                         break;
311:                     case HSV_OUT:
312:                         sbggr8_to_rgb(image, surf->pixels, self->width,
313:                                       self->height, surf->format);
314:                         rgb_to_hsv(surf->pixels, surf->pixels, self->size,
315:                                    V4L2_PIX_FMT_SBGGR8, surf->format);
316:                         break;
317:                     case YUV_OUT:
318:                         sbggr8_to_rgb(image, surf->pixels, self->width,
319:                                       self->height, surf->format);
320:                         rgb_to_yuv(surf->pixels, surf->pixels, self->size,
321:                                    V4L2_PIX_FMT_SBGGR8, surf->format);
322:                         break;
323:                 }
324:             }
325:             else {
326:                 SDL_UnlockSurface(surf);
327:                 return 0;
328:             }
329:             break;
330:         case V4L2_PIX_FMT_YUV420:
331:             if (buffer_size >= (self->size * 3) / 2) {
332:                 switch (self->color_out) {
333:                     case YUV_OUT:
334:                         yuv420_to_yuv(image, surf->pixels, self->width,
335:                                       self->height, surf->format);
336:                         break;
337:                     case RGB_OUT:
338:                         yuv420_to_rgb(image, surf->pixels, self->width,
339:                                       self->height, surf->format);
340:                         break;
341:                     case HSV_OUT:
342:                         yuv420_to_rgb(image, surf->pixels, self->width,
343:                                       self->height, surf->format);
344:                         rgb_to_hsv(surf->pixels, surf->pixels, self->size,
345:                                    V4L2_PIX_FMT_YUV420, surf->format);
346:                         break;
347:                 }
348:             }
349:             else {
350:                 SDL_UnlockSurface(surf);
351:                 return 0;
352:             }
353:             break;
354:     }
355:     SDL_UnlockSurface(surf);
356:     return 1;
357: }
