359: /* query each buffer to see if it contains a frame ready to take */
360: int
361: v4l2_query_buffer(pgCameraObject *self)
362: {
363:     unsigned int i;
364: 
365:     for (i = 0; i < self->n_buffers; ++i) {
366:         struct v4l2_buffer buf;
367: 
368:         CLEAR(buf);
369: 
370:         buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
371:         buf.memory = V4L2_MEMORY_MMAP;
372:         buf.index = i;
373: 
374:         if (-1 == v4l2_xioctl(self->fd, VIDIOC_QUERYBUF, &buf)) {
375:             PyErr_Format(PyExc_MemoryError,
376:                          "ioctl(VIDIOC_QUERYBUF) failure : %d, %s", errno,
377:                          strerror(errno));
378:             return 0;
379:         }
380: 
381:         /*  is there a buffer on outgoing queue ready for us to take? */
382:         if (buf.flags & V4L2_BUF_FLAG_DONE)
383:             return 1;
384:     }
385: 
386:     /* no buffer ready to take */
387:     return 0;
388: }
