491: v4l2_init_mmap(pgCameraObject *self)
492: {
493:     struct v4l2_requestbuffers req;
494: 
495:     CLEAR(req);
496: 
497:     /* 2 is the minimum possible, and some drivers will force a higher count.
498:        It will likely result in buffer overruns, but for purposes of gaming,
499:        it is probably better to drop frames than get old frames. */
500:     req.count = 2;
501:     req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
502:     req.memory = V4L2_MEMORY_MMAP;
503: 
504:     if (-1 == v4l2_xioctl(self->fd, VIDIOC_REQBUFS, &req)) {
505:         if (EINVAL == errno) {
506:             PyErr_Format(PyExc_MemoryError,
507:                          "%s does not support memory mapping",
508:                          self->device_name);
509:             return 0;
510:         }
511:         else {
512:             PyErr_Format(PyExc_MemoryError,
513:                          "ioctl(VIDIOC_REQBUFS) failure : %d, %s", errno,
514:                          strerror(errno));
515:             return 0;
516:         }
517:     }
518: 
519:     if (req.count < 2) {
520:         PyErr_Format(PyExc_MemoryError, "Insufficient buffer memory on %s\n",
521:                      self->device_name);
522:         return 0;
523:     }
524: 
525:     self->buffers = calloc(req.count, sizeof(*self->buffers));
526: 
527:     if (!self->buffers) {
528:         PyErr_Format(PyExc_MemoryError, "Out of memory");
529:         return 0;
530:     }
531: 
532:     for (self->n_buffers = 0; self->n_buffers < req.count; ++self->n_buffers) {
533:         struct v4l2_buffer buf;
534: 
535:         CLEAR(buf);
536: 
537:         buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
538:         buf.memory = V4L2_MEMORY_MMAP;
539:         buf.index = self->n_buffers;
540: 
541:         if (-1 == v4l2_xioctl(self->fd, VIDIOC_QUERYBUF, &buf)) {
542:             PyErr_Format(PyExc_MemoryError,
543:                          "ioctl(VIDIOC_QUERYBUF) failure : %d, %s", errno,
544:                          strerror(errno));
545:             return 0;
546:         }
547: 
548:         self->buffers[self->n_buffers].length = buf.length;
549:         self->buffers[self->n_buffers].start =
550:             mmap(NULL /* start anywhere */, buf.length,
551:                  PROT_READ | PROT_WRITE /* required */,
552:                  MAP_SHARED /* recommended */, self->fd, buf.m.offset);
553: 
554:         if (MAP_FAILED == self->buffers[self->n_buffers].start) {
555:             PyErr_Format(PyExc_MemoryError, "mmap failure : %d, %s", errno,
556:                          strerror(errno));
557:             return 0;
558:         }
559:     }
560: 
561:     return 1;
562: }
