283: /**
284:  * Sets the list of target atoms available in the clipboard.
285:  *
286:  * \param data The clipboard dictionary.
287:  * \param display The requesting Display.
288:  * \param window The requesting Window.
289:  * \param property The request property to place the list into.
290:  */
291: static void
292: _set_targets(PyObject *data, Display *display, Window window, Atom property)
293: {
294:     int i;
295:     char *format;
296:     PyObject *list = PyDict_Keys(data);
297:     PyObject *chars;
298:     int amount = PyList_Size(list);
299:     /* All types plus the TARGETS and a TIMESTAMP atom. */
300:     Atom *targets = malloc((amount + 2) * sizeof(Atom));
301:     if (targets == NULL)
302:         return;
303:     memset(targets, 0, (amount + 2) * sizeof(Atom));
304:     targets[0] = _atom_TARGETS;
305:     targets[1] = _atom_TIMESTAMP;
306:     for (i = 0; i < amount; i++) {
307:         chars = PyUnicode_AsASCIIString(PyList_GetItem(list, i));
308:         if (!chars) {
309:             return;
310:         }
311:         format = PyBytes_AsString(chars);
312:         targets[i + 2] = _convert_format(format);
313:         Py_DECREF(chars);
314:     }
315:     XChangeProperty(display, window, property, XA_ATOM, 32, PropModeReplace,
316:                     (unsigned char *)targets, amount + 2);
317: }
