319: /**
320:  * Places the requested Atom data into a Window.
321:  *
322:  * \param data The clipboard dictionary.
323:  * \param display The requesting Display.
324:  * \param window The requesting Window.
325:  * \param property The request property to place the list into.
326:  * \param target The target property to place the list into.
327:  * \return 0 if no data for the target is available, 1 on success.
328:  */
329: static int
330: _set_data(PyObject *data, Display *display, Window window, Atom property,
331:           Atom target)
332: {
333:     char *name = _atom_to_string(target);
334:     PyObject *val = PyDict_GetItemString(data, name);
335:     char *value = NULL;
336:     int size;
337: 
338:     if (!val) {
339:         XFree(name);
340:         return 0;
341:     }
342:     size = PyBytes_Size(val);
343:     value = PyBytes_AsString(val);
344: 
345:     /* Send data. */
346:     XChangeProperty(display, window, property, target, 8, PropModeReplace,
347:                     (unsigned char *)value, size);
348:     XFree(name);
349:     return 1;
350: }
