352: /**
353:  * \brief Tries to determine the X window with a valid selection.
354:  *        Default is to check
355:  *         - passed parameter
356:  *         - CLIPBOARD
357:  *         - XA_PRIMARY
358:  *         - XA_SECONDARY
359:  *         - XA_CUT_BUFFER0 - 7
360:  *
361:  *         in this order.
362:  *
363:  * \param selection The Atom type, that should be tried before any of the
364:  *                  fixed XA_* buffers.
365:  * \return The Window handle, that owns the selection or None if none was
366:  *         found.
367:  */
368: static Window
369: _get_scrap_owner(Atom *selection)
370: {
371:     int i = 0;
372:     static Atom buffers[] = {XA_PRIMARY,     XA_SECONDARY,   XA_CUT_BUFFER0,
373:                              XA_CUT_BUFFER1, XA_CUT_BUFFER2, XA_CUT_BUFFER3,
374:                              XA_CUT_BUFFER4, XA_CUT_BUFFER5, XA_CUT_BUFFER6,
375:                              XA_CUT_BUFFER7};
376: 
377:     Window owner = XGetSelectionOwner(SDL_Display, *selection);
378:     if (owner != None)
379:         return owner;
380: 
381:     owner = XGetSelectionOwner(SDL_Display, _atom_CLIPBOARD);
382:     if (owner != None)
383:         return owner;
384: 
385:     while (i < 10) {
386:         owner = XGetSelectionOwner(SDL_Display, buffers[i]);
387:         if (owner != None) {
388:             *selection = buffers[i];
389:             return owner;
390:         }
391:         i++;
392:     }
393: 
394:     return None;
395: }
