604: int
605: pygame_scrap_init(void)
606: {
607:     SDL_SysWMinfo info;
608:     int retval = 0;
609: 
610:     /* Grab the window manager specific information */
611:     SDL_SetError("SDL is not running on known window manager");
612: 
613:     SDL_VERSION(&info.version);
614:     if (SDL_GetWMInfo(&info)) {
615:         /* Save the information for later use */
616:         if (info.subsystem == SDL_SYSWM_X11) {
617:             XWindowAttributes setattrs;
618:             XSetWindowAttributes newattrs;
619: 
620:             newattrs.event_mask = PropertyChangeMask;
621: 
622:             SDL_Display = info.info.x11.display;
623:             SDL_Window = info.info.x11.window;
624:             Lock_Display = info.info.x11.lock_func;
625:             Unlock_Display = info.info.x11.unlock_func;
626: 
627:             Lock_Display();
628: 
629:             /* We need the PropertyNotify event for the timestap, so
630:              * modify the event attributes.
631:              */
632:             XGetWindowAttributes(SDL_Display, SDL_Window, &setattrs);
633:             newattrs.event_mask |= setattrs.all_event_masks;
634:             XChangeWindowAttributes(SDL_Display, SDL_Window, CWEventMask,
635:                                     &newattrs);
636: 
637:             Unlock_Display();
638: 
639:             /* Enable the special window hook events */
640:             SDL_EventState(SDL_SYSWMEVENT, SDL_ENABLE);
641:             SDL_SetEventFilter(_clipboard_filter);
642: 
643:             /* Create the atom types we need. */
644:             _init_atom_types();
645: 
646:             retval = 1;
647:         }
648:         else
649:             SDL_SetError("SDL is not running on X11");
650:     }
651:     if (retval)
652:         _scrapinitialized = 1;
653: 
654:     return retval;
655: }
