657: int
658: pygame_scrap_lost(void)
659: {
660:     int retval;
661: 
662:     if (!pygame_scrap_initialized()) {
663:         PyErr_SetString(pgExc_SDLError, "scrap system not initialized.");
664:         return 0;
665:     }
666: 
667:     Lock_Display();
668:     retval = (XGetSelectionOwner(SDL_Display, GET_CLIPATOM(_currentmode)) !=
669:               SDL_Window);
670:     Unlock_Display();
671: 
672:     return retval;
673: }
