755: pygame_scrap_get(char *type, size_t *count)
756: {
757:     if (!pygame_scrap_initialized()) {
758:         PyErr_SetString(pgExc_SDLError, "scrap system not initialized.");
759:         return NULL;
760:     }
761:     return _get_data_as(GET_CLIPATOM(_currentmode), _convert_format(type),
762:                         count);
