778: char **
779: pygame_scrap_get_types(void)
780: {
781:     char **types;
782:     Atom *targetdata;
783:     unsigned long length;
784: 
785:     if (!pygame_scrap_lost()) {
786:         PyObject *key;
787:         PyObject *chars;
788:         Py_ssize_t pos = 0;
789:         int i = 0;
790:         PyObject *dict =
791:             (_currentmode == SCRAP_SELECTION) ? _selectiondata : _clipdata;
792: 
793:         types = malloc(sizeof(char *) * (PyDict_Size(dict) + 1));
794:         if (!types)
795:             return NULL;
796: 
797:         memset(types, 0, (size_t)(PyDict_Size(dict) + 1));
798:         while (PyDict_Next(dict, &pos, &key, NULL)) {
799:             chars = PyUnicode_AsASCIIString(key);
800:             if (chars) {
801:                 types[i] = strdup(PyBytes_AsString(chars));
802:                 Py_DECREF(chars);
803:             }
804:             else {
805:                 types[i] = NULL;
806:             }
807:             if (!types[i]) {
808:                 /* Could not allocate memory, free anything. */
809:                 int j = 0;
810:                 while (types[j]) {
811:                     free(types[j]);
812:                     j++;
813:                 }
814:                 free(types);
815:                 return NULL;
816:             }
817:             i++;
818:         }
819:         types[i] = NULL;
820:         return types;
821:     }
822: 
823:     targetdata = (Atom *)_get_data_as(GET_CLIPATOM(_currentmode),
824:                                       _atom_TARGETS, &length);
825:     if (length > 0 && targetdata != NULL) {
826:         Atom *data = targetdata;
827:         int count = length / sizeof(Atom);
828:         int i;
829:         char **targets = malloc(sizeof(char *) * (count + 1));
830: 
831:         if (targets == NULL) {
832:             free(targetdata);
833:             return NULL;
834:         }
835:         memset(targets, 0, sizeof(char *) * (count + 1));
836: 
837:         for (i = 0; i < count; i++)
838:             targets[i] = _atom_to_string(data[i]);
839: 
840:         free(targetdata);
841:         return targets;
842:     }
843:     return NULL;
844: }

