191: int
192: pygame_scrap_put(char *type, Py_ssize_t srclen, char *src)
193: {
194:     UINT format;
195:     Py_ssize_t nulledlen = srclen + 1;
196:     HANDLE hMem;
197: 
198:     if (!pygame_scrap_initialized()) {
199:         PyErr_SetString(pgExc_SDLError, "scrap system not initialized.");
200:         return 0;
201:     }
202: 
203:     format = _convert_internal_type(type);
204:     if (format == -1)
205:         format = _convert_format(type);
206: 
207:     if (!OpenClipboard(window_handle))
208:         return 0; /* Could not open the clipboard. */
209: 
210:     if (format == CF_DIB || format == CF_DIBV5)
211:         nulledlen -= sizeof(BITMAPFILEHEADER); /* We won't copy the header */
212: 
213:     hMem = GlobalAlloc((GMEM_MOVEABLE | GMEM_DDESHARE), nulledlen);
214:     if (hMem) {
215:         char *dst = GlobalLock(hMem);
216:         if (dst) {
217:             memset(dst, 0, nulledlen);
218:             if (format == CF_DIB || format == CF_DIBV5)
219:                 memcpy(dst, src + sizeof(BITMAPFILEHEADER), nulledlen - 1);
220:             else
221:                 memcpy(dst, src, srclen);
222:         }
223: 
224:         GlobalUnlock(hMem);
225:         EmptyClipboard();
226:         SetClipboardData(format, hMem);
227: 
228:         if (format == _format_MIME_PLAIN) {
229:             /* Setting SCRAP_TEXT, also set CF_TEXT. */
230:             SetClipboardData(CF_TEXT, hMem);
231:         }
232:     }
233:     else {
234:         /* Could not access the clipboard, raise an error. */
235:         CloseClipboard();
236:         return 0;
237:     }
238: 
239:     CloseClipboard();
240:     return 1;
241: }
