317: char **
318: pygame_scrap_get_types(void)
319: {
320:     UINT format = 0;
321:     char **types = NULL;
322:     char **tmptypes;
323:     int i = 0;
324:     int count = -1;
325:     size_t len;
326:     char tmp[100] = {'\0'};
327:     int size = 0;
328: 
329:     if (!OpenClipboard(window_handle))
330:         return NULL;
331: 
332:     size = CountClipboardFormats();
333:     if (size == 0) {
334:         CloseClipboard();
335:         return NULL; /* No clipboard data. */
336:     }
337: 
338:     for (i = 0; i < size; i++) {
339:         format = EnumClipboardFormats(format);
340:         if (format == 0) {
341:             /* Something wicked happened. */
342:             while (i > 0)
343:                 free(types[i]);
344:             free(types);
345:             CloseClipboard();
346:             return NULL;
347:         }
348: 
349:         /* No predefined name, get the (truncated) name. */
350:         len = _lookup_clipboard_format(format, tmp, 100);
351:         if (len == 0)
352:             continue;
353:         count++;
354: 
355:         tmptypes = realloc(types, sizeof(char *) * (count + 1));
356:         if (!tmptypes) {
357:             while (count > 0) {
358:                 free(types[count]);
359:                 count--;
360:             }
361:             free(types);
362:             CloseClipboard();
363:             return NULL;
364:         }
365:         types = tmptypes;
366:         types[count] = malloc(sizeof(char) * (len + 1));
367:         if (!types[count]) {
368:             while (count > 0) {
369:                 free(types[count]);
370:                 count--;
371:             }
372:             free(types);
373:             CloseClipboard();
374:             return NULL;
375:         }
376: 
377:         memset(types[count], 0, len + 1);
378:         memcpy(types[count], tmp, len);
379:     }
380: 
381:     tmptypes = realloc(types, sizeof(char *) * (count + 1));
382:     if (!tmptypes) {
383:         while (count > 0) {
384:             free(types[count]);
385:             count--;
386:         }
387:         free(types);
388:         CloseClipboard();
389:         return NULL;
390:     }
391:     types = tmptypes;
392:     types[count] = NULL;
393:     CloseClipboard();
394:     return types;
395: }
