54: static NSString *
55: getApplicationName(void)
56: {
57:     const NSDictionary *dict;
58:     NSString *appName = 0;
59: 
60:     /* Determine the application name */
61:     dict = (const NSDictionary *)CFBundleGetInfoDictionary(CFBundleGetMainBundle());
62:     if (dict)
63:         appName = [dict objectForKey: @"CFBundleName"];
64: 
65:     if (![appName length])
66:         appName = [[NSProcessInfo processInfo] processName];
