72: _WMEnable(PyObject *self)
73: {
74:     CPSProcessSerNum psn;
75:     const char* nameString;
76:     NSString* nameNSString;
77: 
78:     if (!CPSGetCurrentProcess(&psn)) {
79:         nameNSString = getApplicationName();
80:         nameString = [nameNSString UTF8String];
81:         CPSSetProcessName(&psn, nameString);
82: 
83:         if (!CPSEnableForegroundOperation(&psn, 0x03, 0x3C, 0x2C, 0x1103)) {
84:             if (CPSSetFrontProcess(&psn))
85:                 return RAISE(pgExc_SDLError, "CPSSetFrontProcess failed");
86:         }
87:         else
88:             return RAISE(pgExc_SDLError, "CPSEnableForegroundOperation failed");
89:     }
90:     else
91:         return RAISE(pgExc_SDLError, "CPSGetCurrentProcess failed");
92: 
93:     Py_RETURN_TRUE;
94: }
