197: _ScrapGet(PyObject *self, PyObject *args)
198: {
199: #if defined (PYGAME_MAC_SCRAP_OLD)
200:     Py_RETURN_NONE;
201: #else
202:     char *scrap_type;
203:     if (!PyArg_ParseTuple(args, "s", &scrap_type))
204:         return NULL;
205: 
206:     // anything else than text is not implemented
207:     if (strcmp(scrap_type, PYGAME_SCRAP_TEXT))
208:         Py_RETURN_NONE;
209: 
210:     NSAutoreleasePool *pool = [[NSAutoreleasePool alloc] init];
211:     NSString *info = [[NSPasteboard generalPasteboard]stringForType:NSPasteboardTypeString];
212:     PyObject *ret = NULL;
213: 
214:     if (info != nil)
215:         ret = PyUnicode_FromString([info UTF8String]);
216: 
217:     [pool release];
218:     if (!ret)
219:         Py_RETURN_NONE;
220:     return ret;
221: #endif
